#pragma once
#ifndef ZENOHCXX_ZENOHC
#define ZENOHCXX_ZENOHC
#endif
#include <fstream>
#include <stdexcept>
#include <system_error>
#include <zenoh.hxx>

#include <iostream>
#include <string>
#include <zenoh/api/sample.hxx>

#include <string>
typedef std::string node_id_t;

enum ROLE {
    FOLLOWER,
    CANDIDATE,
    LEADER
};

typedef struct {
    node_id_t id;
    int term;
} message_t;

// serialisation helpers were generated by ChatGPT
zenoh::Bytes to_bytes(const message_t& message) {
    std::vector<uint8_t> buffer;

    // 1. Serialize string length
    uint32_t len = static_cast<uint32_t>(message.id.size());

    buffer.push_back((len >> 24) & 0xFF);
    buffer.push_back((len >> 16) & 0xFF);
    buffer.push_back((len >> 8) & 0xFF);
    buffer.push_back(len & 0xFF);

    // 2. Serialize string contents
    buffer.insert(
        buffer.end(),
        message.id.begin(),
        message.id.end()
    );

    // 3. Serialize term
    uint32_t term = static_cast<uint32_t>(message.term);

    buffer.push_back((term >> 24) & 0xFF);
    buffer.push_back((term >> 16) & 0xFF);
    buffer.push_back((term >> 8) & 0xFF);
    buffer.push_back(term & 0xFF);

    return zenoh::Bytes(std::move(buffer));
}

bool from_bytes(const zenoh::Bytes& bytes, message_t& message) {
    std::vector<uint8_t> buffer = bytes.as_vector();

    // Minimum size: 4 bytes (length) + 4 bytes (term)
    if (buffer.size() < 8) {
        return false;
    }

    size_t offset = 0;

    // 1. Deserialize string length
    uint32_t len =
        (static_cast<uint32_t>(buffer[0]) << 24) |
        (static_cast<uint32_t>(buffer[1]) << 16) |
        (static_cast<uint32_t>(buffer[2]) << 8) |
        static_cast<uint32_t>(buffer[3]);

    offset += 4;

    // Check that enough bytes remain for string and term
    if (buffer.size() != 4ULL + len + 4ULL) {
        return false;
    }

    // 2. Deserialize string contents
    message.id.assign(
        reinterpret_cast<const char*>(buffer.data() + offset),
        len
    );

    offset += len;

    // 3. Deserialize term
    uint32_t term =
        (static_cast<uint32_t>(buffer[offset]) << 24) |
        (static_cast<uint32_t>(buffer[offset + 1]) << 16) |
        (static_cast<uint32_t>(buffer[offset + 2]) << 8) |
        static_cast<uint32_t>(buffer[offset + 3]);

    message.term = static_cast<int32_t>(term);

    return true;
}


class State {
public:
    node_id_t id;
    ROLE role = ROLE::FOLLOWER;
    node_id_t voted_for; // empty string = not voted in this term

    int get_current_term() {return current_term;}
    int change_current_term(int new_term) {
        // clear voted for from last term
        voted_for = node_id_t();
        current_term = new_term;
        write_state();
        return current_term;
    }
    int inc_current_term() {
        // clear voted for from last term
        voted_for = node_id_t();
        ++current_term;
        write_state();
        return current_term;
    }

    void write_state();
    void read_state();

    State(node_id_t id) : id(id), filename(id + ".data") {
        std::ifstream probe(filename);
        if (!probe) {
            // no persisted state yet -> start fresh
            current_term = 0;
            voted_for.clear();
            write_state();
            return;
        }
        probe.close();
        read_state();
    }

private:
    std::string filename;
    int current_term = 0;
};

// File format (one value per line):
//  <current_term>
//  <voted_for>   (empty line if nobody)
void State::write_state() {
    // write to a temp file first and rename it over the old one, so a crash
    // mid-write never leaves a half-written state file behind
    std::string tmp = filename + ".tmp";
    {
        std::ofstream out(tmp, std::ios::out | std::ios::trunc);
        if (!out) {
            throw std::runtime_error("cannot open " + tmp + " for writing");
        }
        out << current_term << '\n'
            << voted_for << '\n';
        out.flush();
        if (!out) {
            throw std::runtime_error("failed writing " + tmp);
        }
    }
    if (std::rename(tmp.c_str(), filename.c_str()) != 0) {
        throw std::system_error(errno, std::generic_category(),
                                "rename " + tmp + " -> " + filename);
    }
}

void State::read_state() {
    std::ifstream in(filename);
    if (!in) {
        throw std::runtime_error("cannot open " + filename + " for reading");
    }

    std::string line;
    if (!std::getline(in, line)) throw std::runtime_error("missing role in " + filename);
    current_term = std::stoi(line);

    // voted_for may be an empty line
    if (!std::getline(in, voted_for)) voted_for.clear();
}